 isles.","category":"physical"}]}],"relationships":[{"id":"rel_mara_tobin_suspect","source_character_id":"chr_mara_voss","target_character_id":"chr_tobin_hale","relationship_type":"rival","description":"Mara Voss suspects Tobin Hale because his alibi rests on manifests he altered, and her pressure pushes him toward confession."},{"id":"rel_isolde_mara_enemy","source_character_id":"chr_isolde_kerr","target_character_id":"chr_mara_voss","relationship_type":"enemy","description":"Isolde Kerr, the hidden blackmailer, sees Mara Voss as the one threat to her scheme and works to mislead and discredit her."},{"id":"rel_isolde_tobin_frame","source_character_id":"chr_isolde_kerr","target_character_id":"chr_tobin_hale","relationship_type":"enemy","description":"Isolde Kerr plants evidence to frame Tobin Hale as the blackmailer, exploiting his known falsifications."},{"id":"rel_bram_mara_client","source_character_id":"chr_bram_oakley","target_character_id":"chr_mara_voss","relationship_type":"ally","description":"Bram Oakley becomes Mara Voss's informant, giving her the letter that links the blackmail demands to Silverspine."},{"id":"rel_isolde_bram_victim","source_character_id":"chr_isolde_kerr","target_character_id":"chr_bram_oakley","relationship_type":"enemy","description":"Isolde Kerr extorts Bram Oakley by threatening to reveal his secret grain sales to the Cartel."}]}
