ernal_conflict":"The Academy board refuses to fund desert surveys, leaving her reliant on secret favours.","arc":"Isolde begins as a detached scholar who treats travellers as instruments. When Kael's returning report shows her chart has a fatal error that would have killed later travellers, Isolde publicly corrects her map, crediting Kael. She ends by prioritising traveller safety over her reputation.","personality_traits":["exacting","curious","proud","dry-witted"],"abilities":[{"name":"Cartography","description":"She can reconstruct routes from fragmentary reports.","category":"mental"}]}],"relationships":[{"id":"rel_dorran_hunts_kael","source_character_id":"chr_dorran_pell","target_character_id":"chr_kael_voss","relationship_type":"pursuer","description":"Dorran Pell is the Drift Cartel collector pursuing Kael Voss across the glass desert to enforce her unpaid wind-debt, creating constant pressure on her journey."},{"id":"rel_kael_distrusts_dorran","source_character_id":"chr_kael_voss","target_character_id":"chr_dorran_pell","relationship_type":"enemy","description":"Kael Voss distrusts and evades Dorran Pell, seeing him as the face of the Cartel levy that ruined her village, until she saves his life."},{"id":"rel_isolde_equips_kael","source_character_id":"chr_isolde_marrow","target_character_id":"chr_kael_voss","relationship_type":"mentor","description":"Isolde Marrow supplies Kael Voss with a map of the glass desert, but her need for data pressures Kael to take a riskier route than she would choose."}]}
